import { buildSchema, graphql } from "graphql";
const schema = buildSchema("type Query { twice(n: Int!): Int! }");

const rootValue = { twice: ({ n }) => n * 2 };
const result = await graphql({ schema, rootValue, source: "query Double($n: Int!) { twice(n: $n) }", variableValues: { n: 4 } });
console.log(JSON.stringify(result.data));
